globalJavaScript:
// Developer helpers. base64 is implemented in pure JS so it works even
// when the QuickJS build has no btoa/atob.
var B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
function toUtf8Bytes(str){
  var out = [];
  for (var i = 0; i < str.length; i++){
    var c = str.charCodeAt(i);
    if (c < 0x80){ out.push(c); }
    else if (c < 0x800){ out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f)); }
    else if (c >= 0xd800 && c < 0xdc00){
      var c2 = str.charCodeAt(++i);
      var cp = 0x10000 + ((c & 0x3ff) << 10) + (c2 & 0x3ff);
      out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else { out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f)); }
  }
  return out;
}
function base64Encode(str){
  var b = toUtf8Bytes(String(str || "")), out = "";
  for (var i = 0; i < b.length; i += 3){
    var b0 = b[i], b1 = b[i + 1], b2 = b[i + 2];
    out += B64[b0 >> 2];
    out += B64[((b0 & 3) << 4) | ((b1 || 0) >> 4)];
    out += (i + 1 < b.length) ? B64[((b1 & 15) << 2) | ((b2 || 0) >> 6)] : "=";
    out += (i + 2 < b.length) ? B64[b2 & 63] : "=";
  }
  return out;
}
function uuid4(){
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function(c){
    var r = (Math.random() * 16) | 0;
    var v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}
function slugify(s){
  return String(s || "").toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}
